# CT43 generic rig posing engine (runs inside Blender).
# Characters are posed by targets in CHARACTER-LOCAL space: origin on the floor between the feet,
# forward = -Y, character's left = +X, up = +Z. Two-bone IK for arms and legs, lean/twist for spine/head.
import bpy, math
from mathutils import Vector, Matrix, Quaternion

D = math.radians

def rig_type(arm):
    b = arm.data.bones
    if "DEF-spine.006" in b and "DEF-upper_arm.L" in b: return "rigify"
    if "Hips" in b and "LeftArm" in b: return "mixamo"
    if "mixamorig:Hips" in b: return "mixamorig"
    return "other"

def roles(arm):
    t = rig_type(arm)
    if t == "rigify":
        R = {"ctl": "root", "spine": ["DEF-spine", "DEF-spine.001", "DEF-spine.002", "DEF-spine.003"],
             "neck": ["DEF-spine.004", "DEF-spine.005"], "head": ["DEF-spine.006"], "jaw": "DEF-jaw"}
        for s in "LR":
            R["arm" + s] = ["DEF-upper_arm.%s" % s, "DEF-upper_arm.%s.001" % s]
            R["fore" + s] = ["DEF-forearm.%s" % s, "DEF-forearm.%s.001" % s]
            R["hand" + s] = "DEF-hand.%s" % s
            R["thigh" + s] = ["DEF-thigh.%s" % s, "DEF-thigh.%s.001" % s]
            R["shin" + s] = ["DEF-shin.%s" % s, "DEF-shin.%s.001" % s]
            R["foot" + s] = "DEF-foot.%s" % s
    else:
        p = "mixamorig:" if t == "mixamorig" else ""
        R = {"ctl": p + "Hips", "spine": [p + "Spine", p + "Spine1", p + "Spine2"], "neck": [p + "Neck"], "head": [p + "Head"], "jaw": p + "Jaw"}
        for s, w in (("L", "Left"), ("R", "Right")):
            R["arm" + s] = [p + w + "Arm"]; R["fore" + s] = [p + w + "ForeArm"]; R["hand" + s] = p + w + "Hand"
            R["thigh" + s] = [p + w + "UpLeg"]; R["shin" + s] = [p + w + "Leg"]; R["foot" + s] = p + w + "Foot"
    names = set(b.name for b in arm.data.bones)
    for k, v in list(R.items()):
        if isinstance(v, list): R[k] = [x for x in v if x in names]
        elif v not in names: R[k] = None
    if not R["spine"] and R["ctl"] is None: raise RuntimeError("unknown rig")
    return t, R

def strip_rig(arm):
    """remove constraints, drivers and actions so bases fully control deform bones; make DEF bones a clean tree."""
    if arm.animation_data:
        arm.animation_data.action = None
        for d in list(arm.animation_data.drivers):
            try: arm.animation_data.drivers.remove(d)
            except Exception: pass
    for pb in arm.pose.bones:
        for c in list(pb.constraints): pb.constraints.remove(c)
        pb.rotation_mode = "QUATERNION"
        pb.location = (0, 0, 0); pb.rotation_quaternion = (1, 0, 0, 0); pb.scale = (1, 1, 1)
    # meshes: drop shape key drivers
    for o in bpy.data.objects:
        if o.type == "MESH" and o.parent == arm and o.data.shape_keys and o.data.shape_keys.animation_data:
            for d in list(o.data.shape_keys.animation_data.drivers):
                try: o.data.shape_keys.animation_data.drivers.remove(d)
                except Exception: pass
    if rig_type(arm) != "rigify": return
    bones = arm.data.bones
    newpar = {}
    for b in bones:
        if not b.use_deform or b.parent is None or b.parent.use_deform: continue
        p = b.parent; target = None
        while p is not None:
            if p.name.startswith("ORG-"):
                cand = "DEF-" + p.name[4:]
                if cand in bones and cand != b.name and bones[cand].use_deform:
                    target = cand; break
            p = p.parent
        if target: newpar[b.name] = target
    if not newpar: return
    vl = bpy.context.view_layer
    for o in vl.objects: o.select_set(False)
    vl.objects.active = arm; arm.select_set(True)
    hid = arm.hide_viewport; arm.hide_viewport = False
    try: arm.hide_set(False)
    except Exception: pass
    bpy.ops.object.mode_set(mode="EDIT")
    eb = arm.data.edit_bones
    for n, p in newpar.items():
        # avoid cycles
        q = eb[p]; ok = True
        while q is not None:
            if q.name == n: ok = False; break
            q = q.parent
        if ok:
            eb[n].use_connect = False; eb[n].parent = eb[p]
    bpy.ops.object.mode_set(mode="OBJECT")
    arm.hide_viewport = hid

class Rig:
    def __init__(self, tag, arm):
        self.tag = tag; self.arm = arm
        self.type, self.R = roles(arm)
        self.bones = arm.data.bones
        self.order = []
        def walk(b):
            self.order.append(b.name)
            for c in b.children: walk(c)
        for b in self.bones:
            if b.parent is None: walk(b)
        self.rest = {b.name: b.matrix_local.copy() for b in self.bones}
        self.relrest = {b.name: (b.parent.matrix_local.inverted() @ b.matrix_local) if b.parent else b.matrix_local.copy() for b in self.bones}
        self.role_of = {}
        R = self.R
        for s in "LR":
            for i, b in enumerate(R["arm" + s]): self.role_of[b] = ("arm", s)
            for b in R["fore" + s]: self.role_of[b] = ("fore", s)
            for b in R["thigh" + s]: self.role_of[b] = ("thigh", s)
            for b in R["shin" + s]: self.role_of[b] = ("shin", s)
            if R["hand" + s]: self.role_of[R["hand" + s]] = ("hand", s)
            if R["foot" + s]: self.role_of[R["foot" + s]] = ("foot", s)
        for b in R["spine"]: self.role_of[b] = ("spine", None)
        for b in R["neck"]: self.role_of[b] = ("neck", None)
        for b in R["head"]: self.role_of[b] = ("head", None)
        if R["ctl"]: self.role_of[R["ctl"]] = ("ctl", None)
        if R.get("jaw"): self.role_of[R["jaw"]] = ("jaw", None)

    def setup(self, M_al):
        """M_al: armature space -> character local."""
        self.M_al = M_al.copy(); self.M_la = M_al.inverted()
        self.A3 = self.M_al.to_3x3().normalized(); self.B3 = self.M_la.to_3x3().normalized()
        self.sc = self.M_al.to_scale()[0]
        R = self.R
        rp = lambda n: self.M_al @ self.rest[n].translation
        self.rest_pos = rp
        self.hip0 = (rp(R["thighL"][0]) + rp(R["thighR"][0])) / 2
        self.Lu = {}; self.Lf = {}; self.Lt = {}; self.Ls = {}; self.foot0 = {}; self.sh0 = {}; self.hand0 = {}
        for s in "LR":
            self.Lu[s] = (rp(R["fore" + s][0]) - rp(R["arm" + s][0])).length
            self.Lf[s] = (rp(R["hand" + s]) - rp(R["fore" + s][0])).length
            self.Lt[s] = (rp(R["shin" + s][0]) - rp(R["thigh" + s][0])).length
            self.Ls[s] = (rp(R["foot" + s]) - rp(R["shin" + s][0])).length
            self.foot0[s] = rp(R["foot" + s]); self.sh0[s] = rp(R["arm" + s][0]); self.hand0[s] = rp(R["hand" + s])
        self.head0 = rp(R["head"][0])
        self.height = self.head0.z + 0.2

    def rotl(self, pitch, roll, yaw):
        """rotation in character local: pitch = bend forward (toward -Y), roll = lean to character's left (+X), yaw = turn left."""
        return Matrix.Rotation(D(yaw), 3, "Z") @ Matrix.Rotation(D(roll), 3, "Y") @ Matrix.Rotation(D(pitch), 3, "X")

    def solve(self, P):
        R = self.R
        pose = {}
        hip = Vector(P.get("hip", self.hip0)); hrot = P.get("hrot", (0, 0, 0))
        lean = P.get("lean", (0, 0, 0)); headp = P.get("head", (0, 0, 0))
        ns = max(1, len(R["spine"])); nn = len(R["neck"]); nh = len(R["head"])
        joint = {}
        for b in self.order:
            bone = self.bones[b]
            par = bone.parent.name if bone.parent else None
            N = (pose[par] @ self.relrest[b]) if par else self.rest[b].copy()
            role = self.role_of.get(b)
            if role is None:
                pose[b] = N; continue
            kind, s = role
            if kind == "ctl":
                Rl = self.rotl(*hrot)
                Ra = (self.B3 @ Rl @ self.A3).to_4x4()
                h0 = self.M_la @ self.hip0; h1 = self.M_la @ hip
                pose[b] = Matrix.Translation(h1) @ Ra @ Matrix.Translation(-h0) @ N
                continue
            if kind in ("spine", "neck", "head"):
                if kind == "spine": f = 1.0 / ns; ang = lean
                elif kind == "neck": f = 0.45 / max(1, nn); ang = headp
                else: f = 0.55 / max(1, nh); ang = headp
                Rl = self.rotl(ang[0] * f, ang[1] * f, 0)
                cur = (N.to_3x3() @ Vector((0, 1, 0))).normalized()
                d = (self.B3 @ Rl @ self.A3 @ cur).normalized()
                pose[b] = self._aim(N, d, ang[2] * f)
                continue
            if kind == "jaw":
                j = P.get("jaw", 0.0)
                if j:
                    rot = (self.B3 @ self.rotl(j, 0, 0) @ self.A3) @ N.to_3x3()
                    pose[b] = Matrix.Translation(N.translation) @ rot.to_4x4()
                else: pose[b] = N
                continue
            if kind == "arm":
                key = "elb" + s
                if key not in joint:
                    S = N.translation
                    T = self.M_la @ Vector(P["hand" + s])
                    pole = self.B3 @ Vector(P.get("pole" + s, (0.5 if s == "L" else -0.5, 0.8, -0.3))).normalized()
                    E, T2 = self._ik(S, T, self.Lu[s] / self.sc, self.Lf[s] / self.sc, pole)
                    joint[key] = E; joint["wri" + s] = T2
                pose[b] = self._aim(N, (joint[key] - N.translation).normalized(), 0)
                continue
            if kind == "fore":
                pose[b] = self._aim(N, (joint["wri" + s] - N.translation).normalized(), 0)
                continue
            if kind == "hand":
                hr = P.get("hrot" + s)
                if hr:
                    Rl = self.rotl(*hr)
                    rot = (self.B3 @ Rl @ self.A3) @ N.to_3x3()
                    pose[b] = Matrix.Translation(N.translation) @ rot.to_4x4()
                else:
                    pose[b] = N
                continue
            if kind == "thigh":
                key = "kne" + s
                if key not in joint:
                    S = N.translation
                    T = self.M_la @ Vector(P["foot" + s])
                    pole = self.B3 @ Vector(P.get("knee" + s, (0.1 if s == "L" else -0.1, -1.0, 0.0))).normalized()
                    E, T2 = self._ik(S, T, self.Lt[s] / self.sc, self.Ls[s] / self.sc, pole)
                    joint[key] = E; joint["ank" + s] = T2
                pose[b] = self._aim(N, (joint[key] - N.translation).normalized(), 0)
                continue
            if kind == "shin":
                pose[b] = self._aim(N, (joint["ank" + s] - N.translation).normalized(), 0)
                continue
            if kind == "foot":
                # keep the rest orientation in character space (flat on the floor), optional pitch
                fp = P.get("fpitch" + s, 0.0)
                rot = self.rest[b].to_3x3()
                if fp:
                    rot = (self.B3 @ self.rotl(fp, 0, 0) @ self.A3) @ rot
                pose[b] = Matrix.Translation(N.translation) @ rot.to_4x4()
                continue
            pose[b] = N
        self.pose = pose
        basis = {}
        for b in self.order:
            bone = self.bones[b]
            if bone.parent: basis[b] = (pose[bone.parent.name] @ self.relrest[b]).inverted() @ pose[b]
            else: basis[b] = self.rest[b].inverted() @ pose[b]
        return basis

    def _aim(self, N, d, twist_deg):
        cur = (N.to_3x3() @ Vector((0, 1, 0))).normalized()
        q = cur.rotation_difference(d)
        if twist_deg: q = Quaternion(d, D(twist_deg)) @ q
        rot = q.to_matrix() @ N.to_3x3()
        return Matrix.Translation(N.translation) @ rot.to_4x4()

    def _ik(self, S, T, L1, L2, pole):
        d = T - S; dist = d.length
        reach = (L1 + L2) * 0.995
        if dist > reach:
            T = S + d.normalized() * reach; d = T - S; dist = reach
        dist = max(dist, abs(L1 - L2) + 1e-4)
        dn = d.normalized()
        a = (L1 * L1 - L2 * L2 + dist * dist) / (2 * dist)
        h = math.sqrt(max(0.0, L1 * L1 - a * a))
        pp = pole - dn * pole.dot(dn)
        if pp.length < 1e-6: pp = dn.orthogonal()
        pp.normalize()
        return S + dn * a + pp * h, T

    def loc_of(self, bone, tail=False):
        M = self.pose[bone]
        p = (M @ Vector((0, self.bones[bone].length, 0))) if tail else M.translation
        return self.M_al @ p

    def key(self, basis, frame):
        pb = self.arm.pose.bones
        for b, M in basis.items():
            if b not in self.role_of and M.to_quaternion().angle < 1e-5 and M.translation.length < 1e-6:
                continue
            p = pb[b]
            loc, rot, sca = M.decompose()
            p.rotation_quaternion = rot
            p.keyframe_insert("rotation_quaternion", frame=frame)
            if loc.length > 1e-6 or self.role_of.get(b, ("",))[0] == "ctl":
                p.location = loc
                p.keyframe_insert("location", frame=frame)

def blend(a, b, k):
    out = dict(a)
    for key, vb in b.items():
        va = a.get(key, vb)
        if isinstance(vb, (tuple, list, Vector)):
            out[key] = tuple(va[i] + (vb[i] - va[i]) * k for i in range(len(vb)))
        else:
            out[key] = va + (vb - va) * k
    return out

EOF_RIG
